import{_ as e,o as t,c as i,a2 as o}from"./chunks/framework.Do1fvF3d.js";const m=JSON.parse('{"title":"Terms and conditions","description":"","frontmatter":{},"headers":[],"relativePath":"en/legal/terminos.md","filePath":"en/legal/terminos.md","lastUpdated":null}'),r={name:"en/legal/terminos.md"};function n(s,a,l,c,h,d){return t(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="terms-and-conditions" tabindex="-1">Terms and conditions <a class="header-anchor" href="#terms-and-conditions" aria-label="Permalink to &quot;Terms and conditions&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Draft</p><p>This document is a draft pending legal review. This English version is a courtesy translation; the <a href="/Tranqui/legal/terminos">Spanish version</a> prevails.</p></div><p><strong>Version:</strong> 2026-10-03</p><h2 id="_1-the-service" tabindex="-1">1. The service <a class="header-anchor" href="#_1-the-service" aria-label="Permalink to &quot;1. The service&quot;">​</a></h2><p>Tranqui identifies calls and helps block spam using information contributed by the community. It is free and open source (AGPL-3.0).</p><h2 id="_2-requirements" tabindex="-1">2. Requirements <a class="header-anchor" href="#_2-requirements" aria-label="Permalink to &quot;2. Requirements&quot;">​</a></h2><p>You must be 18 or older, or have the authorization of your legal guardians.</p><h2 id="_3-acceptable-use" tabindex="-1">3. Acceptable use <a class="header-anchor" href="#_3-acceptable-use" aria-label="Permalink to &quot;3. Acceptable use&quot;">​</a></h2><p>You may not:</p><ul><li>report numbers as spam knowing they are not, or coordinate false reports;</li><li>use Tranqui to harass or identify people;</li><li>try to extract data massively or automatically;</li><li>use offensive labels or labels containing other people&#39;s personal data.</li></ul><p>We may limit or close accounts that break these rules.</p><h2 id="_4-community-information" tabindex="-1">4. Community information <a class="header-anchor" href="#_4-community-information" aria-label="Permalink to &quot;4. Community information&quot;">​</a></h2><p>Names and spam markings come from what other users contribute. We do our best for them to be correct, but they can be wrong. If your number is shown wrongly, <a href="/Tranqui/en/guia/apelacion">ask for a review</a>.</p><h2 id="_5-availability" tabindex="-1">5. Availability <a class="header-anchor" href="#_5-availability" aria-label="Permalink to &quot;5. Availability&quot;">​</a></h2><p>The service is provided &quot;as is&quot;. If there is no connection or the service does not respond, calls ring normally.</p><h2 id="_6-privacy" tabindex="-1">6. Privacy <a class="header-anchor" href="#_6-privacy" aria-label="Permalink to &quot;6. Privacy&quot;">​</a></h2><p>Data processing is governed by the <a href="/Tranqui/en/legal/politica-de-tratamiento">Data processing policy</a>.</p><h2 id="_7-contact" tabindex="-1">7. Contact <a class="header-anchor" href="#_7-contact" aria-label="Permalink to &quot;7. Contact&quot;">​</a></h2><p><span class="placeholder">[CONTACT EMAIL]</span></p>',19)])])}const p=e(r,[["render",n]]);export{m as __pageData,p as default};
